<div class="row justify-content-center"><div class="col-lg-8"><a class="small text-decoration-none" href="/calendar"><i class="bi bi-arrow-left me-1"></i>Back to calendar</a><article class="lh-card p-4 p-md-5 mt-3"><span class="lh-kicker"><?= e(date('l, F j, Y', strtotime($event['event_date']))) ?></span><h1 class="lh-page-title mt-2"><?= e($event['title']) ?></h1><div class="d-flex flex-wrap gap-3 text-secondary mb-4"><span><i class="bi bi-geo-alt me-1"></i><?= e($event['location']) ?></span><span><i class="bi bi-person me-1"></i><?= e($event['organizer']) ?></span><?php if ($event['start_time']): ?><span><i class="bi bi-clock me-1"></i><?= e(substr($event['start_time'], 0, 5)) ?><?= $event['end_time'] ? '–'.e(substr($event['end_time'], 0, 5)) : '' ?></span><?php endif; ?></div><p class="lh-lead"><?= nl2br(e($event['description'])) ?></p><?php if ($event['website_url']): ?><a class="btn btn-lh-primary" href="<?= e($event['website_url']) ?>" target="_blank" rel="noopener">Visit event website <i class="bi bi-arrow-up-right ms-2"></i></a><?php endif; ?><?php if ($event['status'] !== 'approved'): ?><div class="alert alert-warning mt-4 mb-0">This submission is currently <?= e($event['status']) ?> and is only visible to you and administrators.</div><?php endif; ?><?php if ((int)$event['submitted_by'] === (int)$user['id'] && $event['status'] === 'pending' && !$materialRequest): ?><hr class="my-4"><h2 class="h5">Request production materials</h2><p class="text-secondary small">Choose the deliverables Lighthouse should prepare if this event is approved.</p><form method="post" action="/events/<?= (int)$event['id'] ?>/material-request" class="d-grid gap-3"><input type="hidden" name="_token" value="<?= e($_SESSION['csrf']) ?>"><div class="d-flex flex-wrap gap-3"><label><input type="checkbox" name="material_types[]" value="video" class="material-type"> Video</label><label><input type="checkbox" name="material_types[]" value="image" class="material-type"> Image</label></div><div id="video-fields" class="border rounded p-3 d-none"><strong>Video requirements</strong><div class="d-flex flex-wrap gap-3 mt-2"><label><input type="checkbox" name="video_formats[]" value="vertical"> Vertical</label><label><input type="checkbox" name="video_formats[]" value="horizontal"> Horizontal</label><label><input type="checkbox" name="video_formats[]" value="square"> Square</label></div><div class="row g-2 mt-1"><div class="col-md-6"><input class="form-control" name="video_duration" placeholder="Duration, e.g. 30 seconds"></div><div class="col-md-6"><input class="form-control" name="video_resolution" placeholder="Resolution, e.g. 1080p"></div></div></div><div id="image-fields" class="border rounded p-3 d-none"><strong>Image requirements</strong><div class="d-flex flex-wrap gap-3 mt-2"><label><input type="checkbox" name="image_formats[]" value="portrait"> Portrait</label><label><input type="checkbox" name="image_formats[]" value="landscape"> Landscape</label><label><input type="checkbox" name="image_formats[]" value="square"> Square</label></div><input class="form-control mt-2" name="image_dimensions" placeholder="Dimensions, e.g. 1080 × 1350 px"></div><textarea class="form-control" name="event_content" rows="3" placeholder="What should the content communicate?" required></textarea><textarea class="form-control" name="additional_instructions" rows="2" placeholder="Additional instructions (optional)"></textarea><button class="btn btn-lh-primary" type="submit">Submit production request</button></form><script>document.querySelectorAll('.material-type').forEach(function (input) { input.addEventListener('change', function () { document.getElementById('video-fields').classList.toggle('d-none', !document.querySelector('[value="video"]:checked')); document.getElementById('image-fields').classList.toggle('d-none', !document.querySelector('[value="image"]:checked')); }); });</script><?php elseif ($materialRequest): ?><hr class="my-4"><a class="btn btn-outline-primary" href="/material-requests/<?= (int)$materialRequest['id'] ?>">View material request</a><?php endif; ?></article></div></div>
